const typography = {
  fontFamily: [
    "Inter",
    "Roboto",
    "Arial",
    "sans-serif",
  ].join(","),

  // Eskom uses bold, strong typography
  h1: {
    fontSize: "3rem",
    fontWeight: 900,
    lineHeight: 1.1,
    letterSpacing: "-0.02em",
    textTransform: "uppercase" as const,
  },

  h2: {
    fontSize: "2.5rem",
    fontWeight: 800,
    lineHeight: 1.15,
    letterSpacing: "-0.01em",
  },

  h3: {
    fontSize: "2rem",
    fontWeight: 800,
    lineHeight: 1.2,
  },

  h4: {
    fontSize: "1.5rem",
    fontWeight: 700,
    lineHeight: 1.25,
  },

  h5: {
    fontSize: "1.25rem",
    fontWeight: 700,
    lineHeight: 1.3,
  },

  h6: {
    fontSize: "1.125rem",
    fontWeight: 700,
    lineHeight: 1.35,
  },

  subtitle1: {
    fontSize: "1rem",
    fontWeight: 600,
    letterSpacing: "0.01em",
  },

  subtitle2: {
    fontSize: "0.875rem",
    fontWeight: 600,
    letterSpacing: "0.01em",
  },

  body1: {
    fontSize: "1rem",
    lineHeight: 1.6,
    fontWeight: 400,
  },

  body2: {
    fontSize: "0.875rem",
    lineHeight: 1.5,
    fontWeight: 400,
  },

  button: {
    textTransform: "uppercase" as const,
    fontWeight: 800,
    fontSize: "0.9375rem",
    letterSpacing: "0.05em",
  },

  caption: {
    fontSize: "0.75rem",
    fontWeight: 500,
    letterSpacing: "0.03em",
  },

  overline: {
    fontSize: "0.75rem",
    fontWeight: 800,
    textTransform: "uppercase" as const,
    letterSpacing: "0.15em",
  },
};

export default typography;
